def metric(data: pd.DataFrame) -> float:
    def ttb_match(row):
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        for i in range(len(a)):
            if a[i] > b[i]:
                return row['response'] == 0
            elif b[i] > a[i]:
                return row['response'] == 1
        return False

    return float(data.apply(ttb_match, axis=1).mean())

